WITH ranked AS (SELECT id, full_name, dept_id, job_title, salary, hire_date, level FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY job_title ORDER BY salary, id) AS dedup_rank FROM employees) ranked WHERE dedup_rank = 1) SELECT level, COUNT_IF(job_title = 'Manager') AS manager_events, ROUND(SUM(salary) / NULLIF(COUNT(CASE WHEN job_title = 'Intern' THEN 1 END), 0), 2) AS salary_per_intern, MAX(salary) AS max_salary FROM ranked GROUP BY level HAVING MAX(salary) > 0;
